using System;using System.IO;using System.Runtime.Serialization.Json;using System.Text;using System.Collections.Concurrent;using System.Threading;
namespace LoopFive {
 public class Snapshot {public long Revision;public SessionConfig Config;public AudioClip[] Clips=new AudioClip[5];}
 public static class Storage {
  public static readonly string DataDirectory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"LoopFive");
  public static byte[] Json<T>(T obj){using(MemoryStream m=new MemoryStream()){new DataContractJsonSerializer(typeof(T)).WriteObject(m,obj);return m.ToArray();}}
  public static T FromJson<T>(byte[] data){if(data.Length>2097152)throw new InvalidDataException("Configuración demasiado grande.");using(MemoryStream m=new MemoryStream(data))return (T)new DataContractJsonSerializer(typeof(T)).ReadObject(m);}
  public static T Clone<T>(T obj){return FromJson<T>(Json(obj));}
  public static Snapshot Capture(Engine e){lock(e.Gate){Snapshot s=new Snapshot{Config=Clone(e.Config),Revision=e.Revision};for(int i=0;i<5;i++)s.Clips[i]=e.Tracks[i].Clip==null?null:e.Tracks[i].Clip.Clone();return s;}}
  public static void Apply(Engine e,Snapshot s){Validate(s.Config);lock(e.Gate){e.Config=s.Config;for(int i=0;i<5;i++){e.Tracks[i]=new Track(e.Config.Tracks[i]);e.Tracks[i].Clip=s.Clips[i];e.Tracks[i].Stop();}e.Beat=0;e.Frames=0;e.ResetDsp();e.Dirty=false;}}
  public static void Atomic(string path,Action<Stream> write){path=Path.GetFullPath(path);string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(FileStream f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){write(f);f.Flush(true);}if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
  public static void Save(string path,Snapshot s){Atomic(path,delegate(Stream stream){using(BinaryWriter w=new BinaryWriter(stream,Encoding.UTF8,true)){w.Write("LOOP5v2");byte[] json=Json(s.Config);w.Write(json.Length);w.Write(json);for(int i=0;i<5;i++){AudioClip clip=s.Clips[i];w.Write(clip==null?0:clip.Length);if(clip==null||clip.Length==0)continue;w.Write(clip.Bpm);w.Write(clip.Beats);for(int j=0;j<clip.Length;j++){w.Write(clip.L[j]);w.Write(clip.R[j]);}}}});}
  public static Snapshot Load(string path){using(BinaryReader r=new BinaryReader(File.Open(path,FileMode.Open,FileAccess.Read,FileShare.Read))){string magic=r.ReadString();if(magic=="LOOP5v1")return LoadV1(r);if(magic!="LOOP5v2")throw new InvalidDataException("Este archivo no es una sesión de LoopFive.");int count=r.ReadInt32();if(count<1||count>2097152||count>r.BaseStream.Length-r.BaseStream.Position)throw new InvalidDataException("Cabecera de sesión dañada.");Snapshot s=new Snapshot{Config=FromJson<SessionConfig>(r.ReadBytes(count))};Validate(s.Config);long total=0;for(int i=0;i<5;i++){int n=r.ReadInt32();if(n<0||n>Engine.MaxSamples||n*8L+(n>0?12:0)>r.BaseStream.Length-r.BaseStream.Position)throw new InvalidDataException("Datos de pista dañados o fuera de límite.");total+=n;if(total>Engine.MaxSamples*3L)throw new InvalidDataException("La sesión supera el límite de memoria (30 minutos estéreo en total).");if(n==0)continue;float bpm=r.ReadSingle();double beats=r.ReadDouble();if(!Finite(bpm)||bpm<20||bpm>300||double.IsNaN(beats)||double.IsInfinity(beats)||beats<=0)throw new InvalidDataException("Tempo de pista inválido.");float[] l=new float[n],rr=new float[n];for(int j=0;j<n;j++){l[j]=MathX.Safe(r.ReadSingle());rr[j]=MathX.Safe(r.ReadSingle());}s.Clips[i]=new AudioClip(l,rr,bpm,beats);}if(r.BaseStream.Position!=r.BaseStream.Length)throw new InvalidDataException("Datos adicionales inesperados en la sesión.");return s;}}
  static Snapshot LoadV1(BinaryReader r){Snapshot s=new Snapshot{Config=new SessionConfig()};s.Config.Bpm=r.ReadInt32();s.Config.Quantize=false;for(int i=0;i<5;i++){TrackConfig t=s.Config.Tracks[i];t.Level=r.ReadSingle();int fx=r.ReadInt32();t.Reverse=r.ReadBoolean();t.LoopSync=false;int n=r.ReadInt32();if(n<0||n>Engine.MaxSamples||n*8L>r.BaseStream.Length-r.BaseStream.Position)throw new InvalidDataException("Sesión v1 dañada.");float[] l=new float[n],rr=new float[n];for(int j=0;j<n;j++){l[j]=MathX.Safe(r.ReadSingle());rr[j]=MathX.Safe(r.ReadSingle());}if(n>0)s.Clips[i]=new AudioClip(l,rr,s.Config.Bpm,n/44100.0*s.Config.Bpm/60);if(fx>0&&i==0){s.Config.TrackFx.Target=1;s.Config.TrackFx.Slots[0]=new FxConfig{On=true,Type=fx==1?"DIST":fx==2?"LPF":"LO-FI"};}}Validate(s.Config);return s;}
  static bool Finite(float v){return !float.IsNaN(v)&&!float.IsInfinity(v);}
  public static void Validate(SessionConfig c){if(c==null||c.Tracks==null||c.Tracks.Length!=5||c.Rhythm==null)throw new InvalidDataException("Configuración incompleta.");if(!Finite(c.Bpm)||c.Bpm<20||c.Bpm>300)throw new InvalidDataException("Tempo inválido.");c.Master=Valid(c.Master,0,2);c.MasterReverb=Valid(c.MasterReverb,0,1);c.MasterLow=Valid(c.MasterLow,-20,20);c.MasterMid=Valid(c.MasterMid,-20,20);c.MasterHigh=Valid(c.MasterHigh,-20,20);c.SyncMode=Math.Max(0,Math.Min(2,c.SyncMode));c.LoopLengthBars=Math.Max(0,Math.Min(128,c.LoopLengthBars));c.InputGain=Valid(c.InputGain,0,4);c.Gate=Valid(c.Gate,0,1);c.AutoThreshold=Valid(c.AutoThreshold,.0001f,1);c.CountInBars=Math.Max(0,Math.Min(4,c.CountInBars));c.SelectedTrack=Math.Max(0,Math.Min(4,c.SelectedTrack));c.Memory=Math.Max(1,Math.Min(99,c.Memory));if(c.Name==null)c.Name="Sesión";if(c.Name.Length>80)c.Name=c.Name.Substring(0,80);
   foreach(TrackConfig t in c.Tracks){if(t==null)throw new InvalidDataException("Falta una pista.");t.Level=Valid(t.Level,0,2);t.Pan=Valid(t.Pan,-1,1);t.Speed=Valid(t.Speed,.5f,2);t.MeasureBeats=Valid(t.MeasureBeats,0,512);t.Feedback=Valid(t.Feedback,0,1);t.StopMode=Math.Max(0,Math.Min(2,t.StopMode));t.DubMode=Math.Max(0,Math.Min(2,t.DubMode));t.Measures=Math.Max(-1,Math.Min(128,t.Measures));t.FadeInBeats=Valid(t.FadeInBeats,.0625f,256);t.FadeOutBeats=Valid(t.FadeOutBeats,.0625f,256);if(t.Name==null)t.Name="Pista";if(t.Name.Length>40)t.Name=t.Name.Substring(0,40);}
   ValidateChain(c.InputFx,true);ValidateChain(c.TrackFx,false);RhythmConfig rc=c.Rhythm;rc.Pattern=Math.Max(0,Math.Min(210,rc.Pattern));rc.Variation=Math.Max(0,Math.Min(3,rc.Variation));rc.Kit=Math.Max(0,Math.Min(15,rc.Kit));rc.Level=Valid(rc.Level,0,2);rc.Swing=Valid(rc.Swing,0,1);rc.BeatsPerBar=Math.Max(2,Math.Min(15,rc.BeatsPerBar));if(rc.Denominator!=4&&rc.Denominator!=8)rc.Denominator=4;if(rc.UserSteps==null||rc.UserSteps.Length!=16)throw new InvalidDataException("Patrón de usuario inválido.");}
  static float Valid(float v,float lo,float hi){if(!Finite(v))throw new InvalidDataException("Un parámetro contiene un número inválido.");return MathX.Clamp(v,lo,hi);}
  static void ValidateChain(ChainConfig c,bool input){if(c==null||c.Slots==null||c.Slots.Length!=16)throw new InvalidDataException("Banco FX incompleto.");c.Bank=Math.Max(0,Math.Min(3,c.Bank));c.Target&=input?3:31;foreach(FxConfig f in c.Slots){if(f==null||Array.IndexOf(input?FxCatalog.Input:FxCatalog.All,f.Type)<0)throw new InvalidDataException("Tipo de efecto desconocido.");if(f.Detail==null)f.Detail=new FxDetail();f.Detail.Validate();f.Amount=Valid(f.Amount,0,1);f.Rate=Valid(f.Rate,0,1);f.Mix=Valid(f.Mix,0,1);f.Feedback=Valid(f.Feedback,0,.94f);f.Beats=Valid(f.Beats,.0625f,16);f.Steps=Math.Max(1,Math.Min(16,f.Steps));f.Note=Math.Max(12,Math.Min(120,f.Note));f.Semitones=Math.Max(-36,Math.Min(48,f.Semitones));if(f.SequenceValues==null||f.SequenceValues.Length!=16)throw new InvalidDataException("Secuencia FX inválida.");for(int i=0;i<16;i++)f.SequenceValues[i]=Valid(f.SequenceValues[i],0,1);}}
  public static void SaveSystem(SystemConfig c){Directory.CreateDirectory(DataDirectory);Atomic(Path.Combine(DataDirectory,"settings.json"),delegate(Stream s){byte[] bytes=Json(c);s.Write(bytes,0,bytes.Length);});}
  public static SystemConfig LoadSystem(){string p=Path.Combine(DataDirectory,"settings.json");try{if(!File.Exists(p))return new SystemConfig();SystemConfig c=FromJson<SystemConfig>(File.ReadAllBytes(p));if(c.Assignments==null||c.Assignments.Length!=16)throw new InvalidDataException();for(int i=0;i<16;i++)if(c.Assignments[i]==null)c.Assignments[i]=new Assignment();KeyDefaults.Ensure(c);return c;}catch{return new SystemConfig();}}
  public static string MemoryPath(int slot){string folder=Path.Combine(DataDirectory,"Memories");Directory.CreateDirectory(folder);return Path.Combine(folder,slot.ToString("00")+".loop5");}
 }
 public static class Wav {
  public static AudioClip Read(string path,float bpm){using(BinaryReader r=new BinaryReader(File.OpenRead(path))){if(new string(r.ReadChars(4))!="RIFF")throw new InvalidDataException("Se necesita WAV RIFF.");r.ReadUInt32();if(new string(r.ReadChars(4))!="WAVE")throw new InvalidDataException("WAV inválido.");int format=0,channels=0,rate=0,bits=0,align=0;long data=-1;int size=0;while(r.BaseStream.Position+8<=r.BaseStream.Length){string id=new string(r.ReadChars(4));uint len=r.ReadUInt32();long start=r.BaseStream.Position,end=start+len;if(end>r.BaseStream.Length)throw new InvalidDataException("WAV truncado.");if(id=="fmt "){if(len<16)throw new InvalidDataException("Cabecera WAV inválida.");format=r.ReadUInt16();channels=r.ReadUInt16();rate=r.ReadInt32();r.ReadInt32();align=r.ReadUInt16();bits=r.ReadUInt16();if(format==65534&&len>=40){r.BaseStream.Position=start+24;format=r.ReadUInt16();}}if(id=="data"&&data<0){if(len>int.MaxValue)throw new InvalidDataException("Audio demasiado grande.");data=start;size=(int)len;}r.BaseStream.Position=end+(len%2);}
   if(data<0||(format!=1&&format!=3)||channels<1||channels>2||rate<8000||rate>192000||align!=channels*bits/8)throw new InvalidDataException("WAV no compatible: usa PCM o float, mono o estéreo, entre 8 y 192 kHz.");if(format==1&&bits!=8&&bits!=16&&bits!=24&&bits!=32||format==3&&bits!=32&&bits!=64)throw new InvalidDataException("Profundidad WAV no compatible.");int count=size/align;long outputCount=(long)Math.Round(count*44100.0/rate);if(outputCount>Engine.MaxSamples)throw new InvalidDataException("El audio supera los 10 minutos por pista.");float[] l=new float[count],rr=new float[count];r.BaseStream.Position=data;for(int i=0;i<count;i++){l[i]=ReadSample(r,format,bits);rr[i]=channels==2?ReadSample(r,format,bits):l[i];}if(rate!=44100){float[] nl=new float[outputCount],nr=new float[outputCount];for(int i=0;i<nl.Length;i++){double pos=i*rate/44100.0;int ix=Math.Min(count-1,(int)pos);float f=(float)(pos-ix);int next=Math.Min(count-1,ix+1);nl[i]=l[ix]+(l[next]-l[ix])*f;nr[i]=rr[ix]+(rr[next]-rr[ix])*f;}l=nl;rr=nr;}return new AudioClip(l,rr,bpm,l.Length/44100.0*bpm/60);}}
  static float ReadSample(BinaryReader r,int format,int bits){if(format==3)return MathX.Safe(bits==32?r.ReadSingle():(float)r.ReadDouble());if(bits==8)return (r.ReadByte()-128)/128f;if(bits==16)return r.ReadInt16()/32768f;if(bits==24){int v=r.ReadByte()|r.ReadByte()<<8|r.ReadByte()<<16;if((v&0x800000)!=0)v|=unchecked((int)0xff000000);return v/8388608f;}return r.ReadInt32()/2147483648f;}
  public static void Header(BinaryWriter w,long frames,bool floating){long length=frames*(floating?8:4);if(length>uint.MaxValue-36)throw new InvalidDataException("El WAV supera el límite RIFF.");w.Write(Encoding.ASCII.GetBytes("RIFF"));w.Write((uint)(length+36));w.Write(Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((ushort)(floating?3:1));w.Write((ushort)2);w.Write(44100);w.Write(floating?352800:176400);w.Write((ushort)(floating?8:4));w.Write((ushort)(floating?32:16));w.Write(Encoding.ASCII.GetBytes("data"));w.Write((uint)length);}
  public static void Write(string path,AudioClip clip,bool floating){if(clip==null)throw new InvalidOperationException("La pista está vacía.");Storage.Atomic(path,delegate(Stream stream){using(BinaryWriter w=new BinaryWriter(stream,Encoding.UTF8,true)){Header(w,clip.Length,floating);for(int i=0;i<clip.Length;i++){if(floating){w.Write(clip.L[i]);w.Write(clip.R[i]);}else{w.Write((short)(MathX.Clamp(clip.L[i],-1,1)*32767));w.Write((short)(MathX.Clamp(clip.R[i],-1,1)*32767));}}}});}
  public static void RenderMix(string path,Snapshot snapshot,int bars){Engine render=new Engine();Storage.Apply(render,snapshot);render.Config.Quantize=false;render.Config.CountInBars=0;render.Config.Monitor=false;render.Config.SinglePlay=false;foreach(Track t in render.Tracks){t.Config.StartMode=0;t.Config.AllStart=true;}render.AllStart();int total=(int)Math.Min(44100*60*30,Math.Round(bars*render.BarBeats*44100*60/render.Config.Bpm));Storage.Atomic(path,delegate(Stream stream){using(BinaryWriter w=new BinaryWriter(stream,Encoding.UTF8,true)){Header(w,total,true);float[] block=new float[1024];int left=total;while(left>0){int n=Math.Min(512,left);render.Process(null,block,n);for(int j=0;j<n*2;j++)w.Write(block[j]);left-=n;}}});}
 }
 public class MasterRecorder:IDisposable {
  readonly object gate=new object();BlockingCollection<float[]> queue;Thread writer;string path;public bool Recording{get;private set;}public string Error;public long Frames;
  public void Start(string filename){Stop();lock(gate){path=filename;using(FileStream probe=new FileStream(path,FileMode.Create,FileAccess.Write)){using(BinaryWriter bw=new BinaryWriter(probe))Wav.Header(bw,0,true);}queue=new BlockingCollection<float[]>(256);Frames=0;Error=null;Recording=true;writer=new Thread(Write){IsBackground=true,Name="LoopFive WAV Writer"};writer.Start();}}
  public void Enqueue(float[] mix){lock(gate){if(!Recording)return;float[] copy=(float[])mix.Clone();if(!queue.TryAdd(copy)){Error="Grabación máster detenida: disco demasiado lento.";Recording=false;queue.CompleteAdding();}}}
  void Write(){try{using(FileStream f=new FileStream(path,FileMode.Open,FileAccess.Write,FileShare.Read)){f.Position=44;using(BinaryWriter w=new BinaryWriter(f)){foreach(float[] samples in queue.GetConsumingEnumerable()){if(Frames+samples.Length/2>(uint.MaxValue-36)/8){Error="Se alcanzó el límite de tamaño WAV.";break;}foreach(float sample in samples)w.Write(sample);Frames+=samples.Length/2;}f.Position=0;Wav.Header(w,Frames,true);}}}catch(Exception e){Error=e.Message;}finally{lock(gate)Recording=false;}}
  public void Stop(){Thread t;lock(gate){Recording=false;if(queue!=null&&!queue.IsAddingCompleted)queue.CompleteAdding();t=writer;writer=null;}if(t!=null)t.Join();lock(gate){if(queue!=null){queue.Dispose();queue=null;}}}
  public void Dispose(){Stop();}
 }
}
